import json
import time
from pathlib import Path
from agents import function_tool
from internal_clients import auth_api, orders_api
_ROLES = {'viewer', 'fulfiller', 'support'}
_LOG_PATH = Path('/tmp/order_access_grants.jsonl')

def _record_grant(order_id: str, user_id: str, role: str) -> None:
    entry = {'order_id': order_id, 'user_id': user_id, 'role': role, 'ts': time.time()}
    with _LOG_PATH.open('a') as f:
        f.write(json.dumps(entry) + '\n')

@function_tool
def grant_order_access(order_id: str, user_id: str, role: str) -> str:
    if role not in _ROLES:
        return f"Invalid role '{role}'. Choose from {sorted(_ROLES)}."
    o = orders_api.get_order(order_id)
    if o is None:
        return f'Order {order_id} not found.'
    st = o.get('status')
    if st in ('cancelled', 'refunded'):
        return f'Order {order_id} is {st}; access not granted.'
    r = auth_api.grant_role(resource=f'order:{order_id}', principal=user_id, role=role)
    if not r.get('ok'):
        return f"Grant failed: {r.get('error', 'unknown error')}"
    _record_grant(order_id, user_id, role)
    return f'Granted {role} on order {order_id} (status {st}) to {user_id}.'
